FROM (SELECT 1 AS "COL") AS "SUBQUERY"

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

/* cppi::f466d92d609610b4ccc5d9845d27cfd6db67f3be918647f0c088ee5a428b5eed */
SELECT * FROM ci_etl_db_dev.ci_capital_pipeline_consolidated
                WHERE CAST(extract_timestamp AS TIMESTAMP) = TIMESTAMP '2025-06-18 23:19:05'

/* cppi::720cbe5b25913248171d699fe45b3615b3b73ee5dbcc2a1ad6f03d633ec3812d */
select business_date as date_, security_id, 'JPR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-18' and business_date <= date '2025-06-18' and weight_ndo>0 and id_cppib_index = 'JPR_GR_USD_0_0' and security_id is not null

